diff --git a/specs/2/SPEC.md b/specs/2/SPEC.md
new file mode 100644
index 0000000..14b01c3
--- /dev/null
+++ b/specs/2/SPEC.md
@@ -0,0 +1,32 @@
+# Issue 2: Splitting a damage charge two ways loses a cent
+
+## Outcome
+
+Every penny of a damage charge is billed to someone. The shares from `splitCharge` add up to the
+charge. Charge D-301 (3333 cents) split two ways gives 1667 and 1666 cents, not 1666 and 1666.
+
+## Requirements
+
+- When a charge does not divide evenly by the number of borrowers, the system shall give each borrower the rounded-down share and hand out the leftover cents one each, starting with the first borrower.
+- The system shall return shares that add up to exactly the charge, for every charge and number of borrowers.
+- The system shall return shares that differ from each other by at most one cent.
+- When a charge divides evenly, the system shall give every borrower the same share.
+
+## Must not change
+
+- Amounts stay integer cents. No floats.
+- `splitCharge(totalCents, ways)` keeps its name, arguments and return type (`number[]` of length `ways`).
+- A negative or non-integer charge, or fewer than one borrower, is still refused with an error.
+- Nothing under `src/auth/` changes.
+- The existing tests in `tests/fees/split.test.ts` stay as they are.
+
+## Out of scope
+
+- Late fees (`src/fees/late.ts`).
+- Weighted or unequal splits.
+- Changes to how `bun run desk split` prints amounts.
+
+## Done when
+
+- The new tests in `tests/fees/split.test.ts` pass, and so do the existing ones.
+- `bun run gate` exits 0.
diff --git a/src/fees/split.ts b/src/fees/split.ts
index 808a476..b7b52c5 100644
--- a/src/fees/split.ts
+++ b/src/fees/split.ts
@@ -4,5 +4,6 @@ export function splitCharge(totalCents: number, ways: number): number[] {
     throw new Error("totalCents must be a whole number of cents");
   if (!Number.isInteger(ways) || ways < 1) throw new Error("ways must be at least 1");
   const share = Math.floor(totalCents / ways);
-  return Array.from({ length: ways }, () => share);
+  const leftover = totalCents - share * ways;
+  return Array.from({ length: ways }, (_, index) => (index < leftover ? share + 1 : share));
 }
diff --git a/tests/fees/split.test.ts b/tests/fees/split.test.ts
index 936c6bf..ae109fa 100644
--- a/tests/fees/split.test.ts
+++ b/tests/fees/split.test.ts
@@ -9,6 +9,34 @@ test("one borrower pays the whole charge", () => {
   expect(splitCharge(3333, 1)).toEqual([3333]);
 });

+test("leftover cents go one each to the first borrowers", () => {
+  expect(splitCharge(3333, 2)).toEqual([1667, 1666]);
+  expect(splitCharge(1000, 3)).toEqual([334, 333, 333]);
+  expect(splitCharge(5, 4)).toEqual([2, 1, 1, 1]);
+});
+
+test("the shares add up to exactly the charge", () => {
+  for (const total of [0, 1, 99, 3333, 10001]) {
+    for (const ways of [1, 2, 3, 4, 7]) {
+      const sum = splitCharge(total, ways).reduce((a, b) => a + b, 0);
+      expect(sum).toBe(total);
+    }
+  }
+});
+
+test("no share differs from another by more than one cent", () => {
+  for (const total of [0, 1, 99, 3333, 10001]) {
+    for (const ways of [1, 2, 3, 4, 7]) {
+      const shares = splitCharge(total, ways);
+      expect(Math.max(...shares) - Math.min(...shares)).toBeLessThanOrEqual(1);
+    }
+  }
+});
+
+test("a charge that divides evenly gives every borrower the same share", () => {
+  expect(splitCharge(900, 3)).toEqual([300, 300, 300]);
+});
+
 test("a negative charge is refused", () => {
   expect(() => splitCharge(-1, 2)).toThrow();
 });

